/**
 * Day-indexed UMBRAL mission geometry, parsed from data/processed/mission_timeline.csv and
 * mission_positions.csv (generated by scripts/). Pure and serializable: no file-system access here.
 * Positions are heliocentric ecliptic J2000 vectors in astronomical units.
 */
import { parseCsv, type CommStatus, type MissionPhase } from "@/features/crew-health-data";

export type Vec3 = readonly [number, number, number];

/** Million kilometres per astronomical unit. */
export const AU_MKM = 149.5978707;

/** Speed of light in kilometres per second. */
const LIGHT_KM_S = 299792.458;

/** Sun–Earth–spacecraft angle below which the link is lost (see data/README.md, NASA ASCEND 2022). */
export const SOLAR_EXCLUSION_DEG = 2;

/** The views start drawing the exclusion zone once the angle drops below this, so its approach can be seen. */
export const EXCLUSION_HINT_BELOW_DEG = 25;

/** Scenario event code of the solar storm in crew_events.csv. */
export const SOLAR_STORM_EVENT = "solar_storm";

export interface MissionGeometry {
  /** Number of mission days; every array below holds one entry per day at index `day - 1`. */
  total: number;
  date: string[];
  phase: (MissionPhase | null)[];
  comm: CommStatus[];
  earth: (Vec3 | null)[];
  mars: (Vec3 | null)[];
  ship: (Vec3 | null)[];
  distEarthMkm: (number | null)[];
  distMarsMkm: (number | null)[];
  delayMin: (number | null)[];
  /** Sun–Earth–spacecraft angle in degrees, as seen from Earth. */
  sunAngleDeg: (number | null)[];
  marsSol: (number | null)[];
  marsLsDeg: (number | null)[];
}

const PHASES: readonly string[] = ["transit_out", "mars_arrival", "surface", "mars_departure", "transit_return", "landed"];

function records(text: string): Record<string, string>[] {
  const [header = [], ...rows] = parseCsv(text);
  const keys = header.map((key) => key.trim());
  return rows.map((cells) => Object.fromEntries(keys.map((key, index) => [key, (cells[index] ?? "").trim()])));
}

function toNumber(raw: string | undefined): number | null {
  if (raw === undefined || raw === "") return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

function toVec(row: Record<string, string> | undefined, body: string): Vec3 | null {
  if (!row) return null;
  const x = toNumber(row[`${body}_x_au`]);
  const y = toNumber(row[`${body}_y_au`]);
  const z = toNumber(row[`${body}_z_au`]);
  return x === null || y === null || z === null ? null : [x, y, z];
}

/** Builds the geometry from the two CSV texts. Missing or non-finite cells become null, never NaN. */
export function parseMissionGeometry(timelineCsv: string, positionsCsv: string): MissionGeometry {
  const timeline = records(timelineCsv)
    .map((row) => ({ row, day: toNumber(row.day) }))
    .filter((entry): entry is { row: Record<string, string>; day: number } => entry.day !== null && Number.isInteger(entry.day) && entry.day > 0)
    .sort((a, b) => a.day - b.day);
  const positions = new Map<number, Record<string, string>>();
  for (const row of records(positionsCsv)) {
    const day = toNumber(row.day);
    if (day !== null) positions.set(day, row);
  }
  const geometry: MissionGeometry = {
    total: timeline.length,
    date: [],
    phase: [],
    comm: [],
    earth: [],
    mars: [],
    ship: [],
    distEarthMkm: [],
    distMarsMkm: [],
    delayMin: [],
    sunAngleDeg: [],
    marsSol: [],
    marsLsDeg: [],
  };
  timeline.forEach(({ row, day }, index) => {
    // The dataset is contiguous from day 1; a gap would shift every index, so fail loudly at build time.
    if (day !== index + 1) throw new Error(`mission_timeline.csv is not contiguous at day ${day}`);
    const vectors = positions.get(day);
    geometry.date.push(row.date ?? "");
    geometry.phase.push(PHASES.includes(row.phase) ? (row.phase as MissionPhase) : null);
    geometry.comm.push(row.comm === "link" || row.comm === "blackout" ? row.comm : "unknown");
    geometry.earth.push(toVec(vectors, "earth"));
    geometry.mars.push(toVec(vectors, "mars"));
    geometry.ship.push(toVec(vectors, "ship"));
    geometry.distEarthMkm.push(toNumber(row.dist_earth_mkm));
    geometry.distMarsMkm.push(toNumber(row.dist_mars_mkm));
    geometry.delayMin.push(toNumber(row.delay_oneway_min));
    geometry.sunAngleDeg.push(toNumber(row.solar_elong_deg));
    geometry.marsSol.push(toNumber(row.mars_sol));
    geometry.marsLsDeg.push(toNumber(row.mars_Ls_deg));
  });
  return geometry;
}

export function clampDay(day: number, total: number): number {
  const rounded = Number.isFinite(day) ? Math.round(day) : 1;
  return Math.min(Math.max(rounded, 1), Math.max(total, 1));
}

/** Position on a fractional mission day, linearly interpolated between the two daily samples. */
export function positionAt(track: readonly (Vec3 | null)[], day: number): Vec3 | null {
  if (!Number.isFinite(day) || track.length === 0) return null;
  const clamped = Math.min(Math.max(day, 1), track.length);
  const lower = Math.floor(clamped);
  const a = track[lower - 1];
  const b = track[Math.min(lower, track.length - 1)];
  if (!a || !b) return null;
  const t = clamped - lower;
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

export function distanceAu(a: Vec3, b: Vec3): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
}

/** Angle Sun–Earth–spacecraft in degrees (the Sun is the origin); null when the craft is at Earth. */
export function sunEarthShipAngle(earth: Vec3, ship: Vec3): number | null {
  const toSun: Vec3 = [-earth[0], -earth[1], -earth[2]];
  const toShip: Vec3 = [ship[0] - earth[0], ship[1] - earth[1], ship[2] - earth[2]];
  const sunLength = Math.hypot(...toSun);
  const shipLength = Math.hypot(...toShip);
  if (sunLength === 0 || shipLength < 1e-6) return null;
  const cosine = (toSun[0] * toShip[0] + toSun[1] * toShip[1] + toSun[2] * toShip[2]) / (sunLength * shipLength);
  return (Math.acos(Math.min(1, Math.max(-1, cosine))) * 180) / Math.PI;
}

/**
 * One-way signal time in minutes: the timeline's Earth distance divided by the speed of light,
 * which keeps sub-second precision. Falls back to the rounded `delay_oneway_min` column.
 */
export function delayMinutes(geometry: MissionGeometry, day: number): number | null {
  const distance = geometry.distEarthMkm[day - 1];
  if (typeof distance === "number") return (distance * 1e6) / LIGHT_KM_S / 60;
  return geometry.delayMin[day - 1] ?? null;
}

/** Signal time for every mission day (index `day - 1`). */
export function delaySeries(geometry: MissionGeometry): (number | null)[] {
  return Array.from({ length: geometry.total }, (_, index) => delayMinutes(geometry, index + 1));
}

/**
 * Day on which the spacecraft is farthest from Earth. Uses the position vectors, which resolve the
 * maximum to a single day; the rounded distance column plateaus over several days around it.
 */
export function farthestDay(geometry: MissionGeometry): number | null {
  let best: number | null = null;
  let bestDistance = -Infinity;
  for (let index = 0; index < geometry.total; index += 1) {
    const earth = geometry.earth[index];
    const ship = geometry.ship[index];
    const distance = earth && ship ? distanceAu(earth, ship) * AU_MKM : geometry.distEarthMkm[index];
    if (typeof distance === "number" && distance > bestDistance) {
      best = index + 1;
      bestDistance = distance;
    }
  }
  return best;
}

export interface DaySpan {
  startDay: number;
  endDay: number;
  count: number;
}

/** Consecutive runs of communication blackout days. */
export function blackoutSpans(comm: readonly CommStatus[]): DaySpan[] {
  const spans: DaySpan[] = [];
  comm.forEach((status, index) => {
    if (status !== "blackout") return;
    const day = index + 1;
    const last = spans.at(-1);
    if (last && last.endDay === day - 1) {
      last.endDay = day;
      last.count += 1;
    } else {
      spans.push({ startDay: day, endDay: day, count: 1 });
    }
  });
  return spans;
}

export type LinkOutlook =
  | { state: "link"; nextBlackout: DaySpan | null; daysToBlackout: number | null }
  | { state: "blackout"; span: DaySpan; dayOfBlackout: number; linkReturnsDay: number | null; daysUntilLink: number | null }
  | { state: "unknown" };

/** Where a mission day sits relative to the communication blackouts in the dataset. */
export function linkOutlook(geometry: MissionGeometry, day: number): LinkOutlook {
  const status = geometry.comm[day - 1];
  const spans = blackoutSpans(geometry.comm);
  if (status === "blackout") {
    const span = spans.find((candidate) => day >= candidate.startDay && day <= candidate.endDay);
    if (!span) return { state: "unknown" };
    const returns = span.endDay + 1 <= geometry.total && geometry.comm[span.endDay] === "link" ? span.endDay + 1 : null;
    return { state: "blackout", span, dayOfBlackout: day - span.startDay + 1, linkReturnsDay: returns, daysUntilLink: returns === null ? null : returns - day };
  }
  if (status === "link") {
    const next = spans.find((candidate) => candidate.startDay > day) ?? null;
    return { state: "link", nextBlackout: next, daysToBlackout: next ? next.startDay - day : null };
  }
  return { state: "unknown" };
}

/** True while the crew is at Mars and close enough to the Sun, seen from Earth, for the exclusion zone to be drawn. */
export function nearConjunction(geometry: MissionGeometry, day: number): boolean {
  const angle = geometry.sunAngleDeg[day - 1];
  const toMars = geometry.distMarsMkm[day - 1];
  return typeof angle === "number" && typeof toMars === "number" && toMars < 0.5 && angle < EXCLUSION_HINT_BELOW_DEG;
}

/** First day in [fromDay, toDay] whose value satisfies the predicate; null when none does. */
export function firstDay(values: readonly (number | null)[], fromDay: number, toDay: number, test: (value: number) => boolean): number | null {
  for (let day = Math.max(1, fromDay); day <= Math.min(toDay, values.length); day += 1) {
    const value = values[day - 1];
    if (typeof value === "number" && test(value)) return day;
  }
  return null;
}

export function phaseDay(geometry: MissionGeometry, phase: MissionPhase): number | null {
  const index = geometry.phase.indexOf(phase);
  return index === -1 ? null : index + 1;
}
